fn inRanges(ranges: []const Range, cp: u21) bool {
    var lo: usize = 0;
    var hi: usize = ranges.len;
    while (lo < hi) {
        const mid = lo + (hi - lo) / 2;
        if (cp < ranges[mid].lo) {
            hi = mid;
        } else if (cp > ranges[mid].hi) {
            lo = mid + 1;
        } else {
            return true;
        }
    }
    return false;
}

fn lookupCase(cp: u21) ?CaseMapping {
    var lo: usize = 0;
    var hi: usize = case_mappings.len;
    while (lo < hi) {
        const mid = lo + (hi - lo) / 2;
        if (cp < case_mappings[mid].cp) {
            hi = mid;
        } else if (cp > case_mappings[mid].cp) {
            lo = mid + 1;
        } else {
            return case_mappings[mid];
        }
    }
    return null;
}

/// True for code points with the Unicode `Alphabetic` property
/// (the regex `\p{Alpha}` in ECMAScript terms).
pub fn isAlphabetic(cp: u21) bool {
    return inRanges(&alphabetic_ranges, cp);
}

/// True for code points in general category N (the regex `\p{N}`).
pub fn isNumber(cp: u21) bool {
    return inRanges(&number_ranges, cp);
}

/// True for code points in general category Lu (the regex `\p{Lu}`).
pub fn isUppercaseLetter(cp: u21) bool {
    return inRanges(&uppercase_letter_ranges, cp);
}

/// True for code points in general category Ll (the regex `\p{Ll}`).
pub fn isLowercaseLetter(cp: u21) bool {
    return inRanges(&lowercase_letter_ranges, cp);
}

/// Simple lowercase mapping (identity for uncased code points).
pub fn toLower(cp: u21) u21 {
    return if (lookupCase(cp)) |m| m.lower else cp;
}

/// Simple uppercase mapping (identity for uncased code points).
pub fn toUpper(cp: u21) u21 {
    return if (lookupCase(cp)) |m| m.upper else cp;
}

test "spot-check generated tables" {
    try std.testing.expectEqual(@as(u21, 0x00E8), toLower(0x00C8)); // È -> è
    try std.testing.expectEqual(@as(u21, 0x0440), toLower(0x0420)); // Р -> р
    try std.testing.expectEqual(@as(u21, 0x00C8), toUpper(0x00E8));
    try std.testing.expect(isAlphabetic(0x6851)); // 桑
    try std.testing.expect(!isAlphabetic('$'));
    try std.testing.expect(isNumber('3'));
    try std.testing.expect(isUppercaseLetter(0x00C8));
    try std.testing.expect(isLowercaseLetter(0x00E8));
    try std.testing.expect(!isUppercaseLetter(0x6851));
}
